#!/usr/bin/env bash
# Part of the Newsroom installer library; sourced by common.sh, never executed.

# --- Install steps ---------------------------------------------------------

nr_install_cli() {
  local bin_dir="$1"
  [ "$NR_DRY_RUN" = "1" ] && { nr_info "would install the newsroom CLI into $bin_dir"; return 0; }
  mkdir -p "$bin_dir"
  local launcher="$bin_dir/newsroom"
  cat > "$launcher" <<EOF
#!/usr/bin/env bash
# Generated by install.sh. Runs the control CLI from the checkout that
# installed it; re-run install.sh if the repository moves.
exec "$NR_REPO_ROOT/bin/newsroom.sh" "\$@"
EOF
  chmod 755 "$launcher"
  ln -sfn "$NR_REPO_ROOT/bin/newsroom.sh" "$bin_dir/newsroom-cli" 2>/dev/null || true
  nr_ok "installed CLI: $launcher"
}

nr_download_models() {
  if [ "$NR_DOWNLOAD_MODELS" = "0" ]; then
    nr_info "skipping model download (--no-models)"
    return 0
  fi
  if [ "$(nr_state_get MODELS_DOWNLOADED)" = "1" ]; then
    nr_ok "local models already downloaded"
    return 0
  fi
  nr_info "downloading local models (Ollama, Whisper, Piper); this can take a while"
  nr_run_compose run --rm model-init
  nr_state_set MODELS_DOWNLOADED 1
  nr_ok "local models ready"
}

nr_run_migrations() {
  if [ "$(nr_state_get MIGRATIONS_APPLIED)" = "1" ]; then
    nr_ok "database migrations already applied"
    return 0
  fi
  nr_info "applying database migrations"
  nr_run_compose run --rm migrate
  nr_state_set MIGRATIONS_APPLIED 1
}

nr_prompt_admin_email() {
  local email="${NEWSROOM_ADMIN_EMAIL:-$(nr_env_get NEWSROOM_ADMIN_EMAIL)}"
  if [ -n "$email" ]; then
    printf '%s' "$email"
    return 0
  fi
  if nr_is_interactive; then
    printf 'Administrator email [admin@example.local]: ' >&2
    local answer=""
    IFS= read -r answer
    printf '%s' "${answer:-admin@example.local}"
    return 0
  fi
  printf 'admin@example.local'
}

nr_create_admin() {
  if [ "$(nr_state_get ADMIN_CREATED)" = "1" ]; then
    nr_ok "administrator account already initialized"
    return 0
  fi

  local email password generated=0
  email="$(nr_prompt_admin_email)"
  password="${NEWSROOM_ADMIN_PASSWORD:-}"

  if [ -z "$password" ]; then
    if nr_is_interactive; then
      local confirm=""
      password="$(nr_read_secret "Administrator password (min 8 chars): ")"
      confirm="$(nr_read_secret "Repeat administrator password: ")"
      if [ "$password" != "$confirm" ]; then
        nr_die "passwords do not match"
      fi
      unset confirm
    else
      password="$(nr_generate_password)"
      generated=1
    fi
  fi

  if [ "${#password}" -lt 8 ]; then
    nr_die "administrator password must be at least 8 characters"
  fi

  nr_info "creating the first administrator: $email"
  if [ "$NR_DRY_RUN" = "1" ]; then
    nr_run_compose run --rm -T api node scripts/create-admin.js --email "$email" --password-stdin
  else
    nr_run_compose_with_stdin "$password" run --rm -T api node scripts/create-admin.js --email "$email" --password-stdin
    nr_state_set ADMIN_CREATED 1
  fi

  if [ "$generated" = "1" ] && [ "$NR_DRY_RUN" = "0" ]; then
    NR_ADMIN_PASSWORD_PRINTED="$password"
  fi
  unset password
}

nr_print_generated_admin_password() {
  if [ -n "$NR_ADMIN_PASSWORD_PRINTED" ]; then
    printf '\n'
    nr_info "Generated administrator password (shown once, not written to disk):"
    printf '%s\n' "$NR_ADMIN_PASSWORD_PRINTED"
    nr_info "Sign in with ${NEWSROOM_ADMIN_EMAIL:-admin@example.local} and change it in Settings."
    printf '\n'
    NR_ADMIN_PASSWORD_PRINTED=""
  fi
}

nr_start_stack() {
  if [ "$NR_START_STACK" = "0" ]; then
    nr_info "skipping stack start (--no-start)"
    return 0
  fi
  nr_info "building and starting the stack (profile: $NR_PROFILE)"
  nr_run_compose up -d --build
  nr_state_set STACK_STARTED 1
  nr_state_set PROFILE "$NR_PROFILE"
  nr_state_set INSTALLED_AT "$(nr_now)"
  nr_ok "stack is running"
}

nr_open_panel() {
  local port
  port="$(nr_env_get PANEL_PORT)"
  port="${port:-8080}"
  if [ "$NR_OPEN_PANEL" = "0" ] || [ "$NR_DRY_RUN" = "1" ]; then
    nr_info "open the panel at http://127.0.0.1:${port}"
    return 0
  fi
  if nr_command_exists xdg-open; then
    xdg-open "http://127.0.0.1:${port}" >/dev/null 2>&1 || true
  elif nr_command_exists open; then
    open "http://127.0.0.1:${port}" >/dev/null 2>&1 || true
  fi
  nr_info "open the panel at http://127.0.0.1:${port}"
}

# --- Uninstall -------------------------------------------------------------

nr_confirm() {
  local prompt="$1"
  if [ "$NR_YES" = "1" ] || ! nr_can_use_tty; then
    return 1
  fi
  local answer=""
  printf '%s [y/N]: ' "$prompt" >&2
  IFS= read -r answer
  case "$answer" in y|Y|yes|YES) return 0 ;; *) return 1 ;; esac
}

nr_uninstall() {
  local purge="$1"
  nr_info "removing the Newsroom stack"
  if [ -f "$NR_COMPOSE_FILE" ]; then
    nr_run_compose down --remove-orphans || nr_warn "docker compose down reported an error"
  else
    nr_warn "compose file not found; no containers were removed"
  fi

  local delete_data=0
  if [ "$purge" = "1" ]; then
    if [ "$NR_YES" = "1" ] || nr_confirm "Delete volumes, local models and the generated .env?"; then
      delete_data=1
    else
      nr_info "keeping volumes, models and .env"
    fi
  fi

  if [ "$delete_data" = "1" ] && [ "$NR_DRY_RUN" = "0" ]; then
    nr_run_compose down --volumes --rmi local --remove-orphans || nr_warn "docker compose down --volumes reported an error"
    rm -rf "$NR_STATE_DIR"
    rm -f "$NR_ENV_FILE"
    nr_ok "volumes, local models, images and .env removed"
  fi

  if [ -n "$NR_BIN_DIR" ] && [ "$NR_DRY_RUN" = "0" ]; then
    rm -f "$NR_BIN_DIR/newsroom" "$NR_BIN_DIR/newsroom-cli"
    nr_ok "removed CLI from $NR_BIN_DIR"
  fi

  nr_ok "uninstall complete"
}
